package com.rikkeibank.customer.web;import com.rikkeibank.common.api.GlobalExceptionHandler;import com.rikkeibank.customer.service.CustomerService;import org.junit.jupiter.api.Test;import org.springframework.test.web.servlet.MockMvc;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.mockito.Mockito.mock;
class CustomerControllerTest{@Test void invalidCreateRequestReturnsStandard400()throws Exception{CustomerService service=mock(CustomerService.class);MockMvc mvc=MockMvcBuilders.standaloneSetup(new CustomerController(service)).setControllerAdvice(new GlobalExceptionHandler()).build();mvc.perform(post("/api/customers").contentType("application/json").content("{\"fullName\":\"\",\"email\":\"not-an-email\",\"phone\":\"\",\"nationalId\":\"\"}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("VALIDATION_ERROR")).andExpect(jsonPath("$.validationErrors.email").exists());}}
